  paths.forEach(path=>path.classList.remove('country-chosen'));
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  // Restart the same short animation when the current marker is chosen again.
  void document.querySelector('#country-outlines').getBoundingClientRect();
